// Phân loại email dựa trên VIP senders, keywords khẩn cấp và loại trừ quảng cáo/newsletter
const email = $input.first().json;

// Chỉ xử lý email chưa đọc
// FIX: Thêm console.log để dễ debug khi email bị bỏ qua
const isRead = email.isRead === true;
if (isRead) {
  console.log(`[SKIP] Email đã đọc: id=${email.id} | subject="${email.subject}" — bỏ qua, không xử lý.`);
  return [];
}

const subject = (email.subject || '').toLowerCase();
const fromAddress = (email.from?.emailAddress?.address || '').toLowerCase();
const fromName = email.from?.emailAddress?.name || '';
const bodyPreview = email.bodyPreview || '';
const bodyContent = (email.body?.content || '').toLowerCase();
const fullText = `${subject} ${fromAddress} ${bodyContent}`;

// Danh sách người gửi VIP cần chú ý ngay lập tức
const vipSenders = [
  'boss@company.com',
  'director@company.com',
  'important-client@corp.com',
  'partner@company.com'
];

// Từ khóa khẩn cấp cần hành động ngay
const urgentKeywords = [
  'urgent', 'khẩn', 'gấp', 'important', 'quan trọng', 'deadline', 'hạn chót',
  'payment', 'thanh toán', 'overdue', 'quá hạn', 'cảnh báo', 'warning', 'incident', 'sự cố'
];

// Từ khóa bản tin hoặc email tự động không quan trọng
const newsletterKeywords = [
  'unsubscribe', 'newsletter', 'digest', 'bản tin', 'hủy đăng ký',
  'no-reply', 'noreply', 'do-not-reply', 'mailing list'
];

// Từ khóa khuyến mãi hoặc quảng cáo
const promoKeywords = [
  'sale', 'discount', 'giảm giá', 'khuyến mãi', 'flash sale', 'ưu đãi',
  'coupon', 'voucher', 'đặc biệt', 'quà tặng', 'offer', 'black friday'
];

const isVip = vipSenders.some(sender => fromAddress.includes(sender));
const hasUrgent = urgentKeywords.some(kw => fullText.includes(kw));
const hasNewsletter = newsletterKeywords.some(kw => fullText.includes(kw));
const hasPromo = promoKeywords.some(kw => fullText.includes(kw));

let category = 'normal';
let action = 'notify_quiet';
let priority = 'medium';

if (isVip || hasUrgent || email.importance === 'high') {
  category = 'important';
  action = 'notify_interactive';
  priority = 'high';
} else if (hasNewsletter || hasPromo) {
  category = 'newsletter_promo';
  action = 'auto_archive';
  priority = 'low';
} else {
  category = 'normal';
  action = 'notify_quiet';
  priority = 'medium';
}

return [{
  json: {
    id: email.id,
    subject: email.subject,
    from: email.from,
    bodyPreview: bodyPreview,
    receivedDateTime: email.receivedDateTime,
    importance: email.importance,
    category: category,
    action: action,
    priority: priority,
    classified_at: new Date().toISOString()
  }
}];

// Build Slack Block Kit payload để gửi interactive message
const d = $input.first().json;
const slackChannelId = $('Config Vars').first().json.slackChannelId;

const fromName = d.from?.emailAddress?.name || 'Không rõ';
const fromAddr = d.from?.emailAddress?.address || '';
const subject  = d.subject || '(Không có tiêu đề)';
const preview  = d.bodyPreview || 'Không có nội dung xem trước.';
const priority = d.priority || 'medium';
const emailId  = d.id || '';
const receivedAt = d.receivedDateTime
  ? new Date(d.receivedDateTime).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })
  : 'Không rõ';

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: '📧 Outlook Inbox Manager', emoji: true }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Email quan trọng mới!* 🔴

*Người gửi:* ${fromName} <${fromAddr}>
*Chủ đề:* ${subject}
*Thời gian:* ${receivedAt}

*Xem trước:*
> ${preview.substring(0, 200)}`
    }
  },
  {
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Lưu trữ 📦', emoji: true },
        style: 'primary',
        value: emailId,
        action_id: 'archive'
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Đánh dấu đã đọc ✅', emoji: true },
        value: emailId,
        action_id: 'mark_read'
      },
      {
        type: 'button',
        text: { type: 'plain_text', text: 'Gắn cờ ⭐️', emoji: true },
        value: emailId,
        action_id: 'flag'
      }
    ]
  }
];

return [{
  json: {
    channel: slackChannelId,
    text: `📧 Email quan trọng từ ${fromName}: ${subject}`,
    blocks: blocks,
    // Pass through email data
    _emailId: emailId,
    _subject: subject
  }
}];

// FIX: Parse payload an toàn với error handling rõ ràng
const body = $input.first().json.body;

if (!body) {
  throw new Error('Không tìm thấy body từ Slack webhook. Kiểm tra lại cấu hình Slack App Interactivity.');
}

if (!body.payload) {
  throw new Error('Không tìm thấy payload trong body. Đảm bảo Slack gửi đúng định dạng application/x-www-form-urlencoded.');
}

let payload;
try {
  payload = JSON.parse(body.payload);
} catch (e) {
  throw new Error(`Không thể parse payload JSON từ Slack: ${e.message}`);
}

if (!payload.actions || payload.actions.length === 0) {
  throw new Error('Payload không chứa actions. Có thể đây không phải sự kiện nút bấm.');
}

const action = payload.actions[0];
const actionId = action.action_id; // 'archive', 'mark_read', 'flag'
const emailId = action.value;      // ID của email Outlook
const responseUrl = payload.response_url;
const userName = payload.user?.username || payload.user?.name || 'unknown';
const channelId = payload.channel?.id;
const messageTs = payload.message?.ts;
const originalBlocks = payload.message?.blocks || [];

return [{
  json: {
    action_id: actionId,
    email_id: emailId,
    response_url: responseUrl,
    user_name: userName,
    channel_id: channelId,
    message_ts: messageTs,
    original_blocks: originalBlocks
  }
}];

// FIX: Lấy dữ liệu từ Parse Slack Payload thông qua $() - an toàn trong cùng một execution
const slackData = $('Parse Slack Payload').first().json;
const originalBlocks = slackData.original_blocks || [];
const actionId = slackData.action_id;
const userName = slackData.user_name;

// Xóa bỏ blocks chứa các nút bấm (actions) để tránh click lặp
const updatedBlocks = originalBlocks.filter(block => block.type !== 'actions');

let actionText = '';
if (actionId === 'archive') {
  actionText = '📦 Đã lưu trữ (Archived)';
} else if (actionId === 'mark_read') {
  actionText = '✅ Đã đánh dấu đã đọc (Marked Read)';
} else if (actionId === 'flag') {
  actionText = '⭐️ Đã gắn nhãn quan trọng (Flagged)';
} else {
  actionText = `❓ Hành động không xác định: ${actionId}`;
}

const processedAt = new Date().toLocaleTimeString('vi-VN', {
  timeZone: 'Asia/Ho_Chi_Minh',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
});

// Thêm context thông báo trạng thái mới bên dưới tin nhắn gốc
updatedBlocks.push({
  "type": "context",
  "elements": [
    {
      "type": "mrkdwn",
      "text": `🟢 *Trạng thái:* ${actionText} | Người xử lý: *@${userName}* lúc ${processedAt}`
    }
  ]
});

return [{
  json: {
    response_url: slackData.response_url,
    payload: {
      blocks: updatedBlocks,
      replace_original: true
    }
  }
}];
